const temp = flow.get("temp");
const ritmo = flow.get("ritmo");
const horas = flow.get("horas");
const ruido = flow.get("ruido");

// Si ningún sensor ha enviado dato todavía
if (temp === null && ritmo === null && horas === null && ruido === null) {
    msg.payload = "⏳ ESPERANDO DATOS...\n\nMueve los sliders para comenzar el monitoreo.";
    msg.ui_update = { color: "#888888" };
    return msg;
}

// Usar 0 solo si el dato llegó explícitamente en null (sensor caído)
const t = temp ?? 36;
const r = ritmo ?? 70;
const h = horas ?? 0;
const n = ruido ?? 0;

let puntos = 0;
let factores = [];

// Temperatura
if (t > 39) { puntos += 3; factores.push("🌡️ Fiebre alta"); }
else if (t > 37.5) { puntos += 1; factores.push("🌡️ Febrícula"); }
else if (t < 35) { puntos += 2; factores.push("🌡️ Hipotermia"); }

// Ritmo cardíaco
if (r > 140) { puntos += 4; factores.push("🫀 Taquicardia crítica"); }
else if (r > 120) { puntos += 3; factores.push("🫀 Taquicardia alta"); }
else if (r > 100) { puntos += 1; factores.push("🫀 Taquicardia leve"); }
else if (r < 50) { puntos += 3; factores.push("🫀 Bradicardia severa"); }
else if (r < 60) { puntos += 1; factores.push("🫀 Bradicardia leve"); }

// Horas trabajadas
if (h >= 12) { puntos += 4; factores.push("⏱️ Exceso crítico de horas"); }
else if (h >= 10) { puntos += 3; factores.push("⏱️ Sobrecarga laboral"); }
else if (h >= 9) { puntos += 1; factores.push("⏱️ Horas extra"); }

// Ruido
if (n > 120) { puntos += 4; factores.push("🔊 Ruido excesivo"); }
else if (n > 100) { puntos += 3; factores.push("🔊 Ruido peligroso"); }
else if (n > 80) { puntos += 1; factores.push("🔊 Ruido alto"); }

const detalle = factores.length > 0
    ? "\n\nFactores detectados:\n" + factores.join("\n")
    : "\n\nSin factores de riesgo activos.";

if (puntos === 0) {
    msg.payload = "🟢 CONDICIÓN ÓPTIMA" + detalle;
    msg.ui_update = { color: "#2bf702" };
}
else if (puntos <= 3) {
    msg.payload = "🟡 ESTRÉS LEVE" + detalle;
    msg.ui_update = { color: "#fbff00" };
}
else if (puntos <= 7) {
    msg.payload = "🟠 ESTRÉS MODERADO" + detalle;
    msg.ui_update = { color: "#ff8800" };
}
else if (puntos <= 11) {
    msg.payload = "🔴 ESTRÉS ALTO" + detalle;
    msg.ui_update = { color: "#ea5353" };
}
else {
    msg.payload = "⚫ COLAPSO CRÍTICO" + detalle;
    msg.ui_update = { color: "#201d1d" };
}

return msg;

const prev = context.get("lastState") || "";
const current = msg.payload || "";

const esCritico = current.includes("ESTRÉS ALTO") || current.includes("COLAPSO CRÍTICO");
const cambio = current !== prev;

context.set("lastState", current);

if (esCritico && cambio) {
    const esColapso = current.includes("COLAPSO");

    msg.payload = esColapso
        ? "⚫ COLAPSO CRÍTICO — Detener actividad de inmediato."
        : "🔴 ESTRÉS ALTO — Revisar condiciones laborales.";

    msg.timeout = esColapso ? 0 : 8000;

    return msg;
}

return null;

let va= msg.payload;
msg.payload = va * 10;
msg.payload=Number(va.toFixed(2));
return msg;

let va = msg.payload;
msg.payload = (va * 3)+ 2.5;
msg.payload = Number(va.toFixed(2));
return msg;

if(msg.payload > 50){
    msg.payload = "Alarma mayor a 50";
    return msg;
}
return null;

if (msg.payload > 90) {
    msg.payload = "Humedad mayor a 90";
    return msg;

}
return null;

let msg1 = { payload: msg.payload.usuario };
let msg2 = { payload: msg.payload.perfil.nombre };
let msg3 = { payload: msg.payload.perfil.apellido };
let msg4 = { payload: msg.payload.perfil.direccion.calle };
let msg5 = { payload: msg.payload.perfil.direccion.ciudad };
return [msg1, msg2, msg3, msg4, msg5];

if(msg.payload.current.is_day == "yes"){
    msg.payload = true;
}
else{
    msg.payload = false;
}

return msg;

